const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "sqlite",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ─── Workspace ────────────────────────────────────────────────────────────────\n\nmodel AgencyWorkspace {\n  id        String   @id @default(cuid())\n  name      String\n  slug      String   @unique\n  createdAt DateTime @default(now())\n\n  users                User[]\n  clients              Client[]\n  projects             Project[]\n  integrationConfigs   DbIntegrationConfig[]\n  agentProviderConfigs DbAgentProviderConfig[]\n  activityEvents       ActivityEvent[]\n  aiRunLogs            AIRunLog[]\n  metaConnections      MetaConnection[]\n  marketInsights       MarketInsight[]\n}\n\n// ─── Users / Auth ─────────────────────────────────────────────────────────────\n\nmodel User {\n  id           String          @id @default(cuid())\n  email        String          @unique\n  name         String\n  passwordHash String\n  // Roles: master | project_manager | social_staff | design_staff | ads_staff | client\n  role         String          @default(\"master\")\n  workspaceId  String\n  workspace    AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  // For client users only — links to the Client they may access\n  clientId     String?\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n}\n\n// ─── Clients ──────────────────────────────────────────────────────────────────\n\nmodel Client {\n  id          String          @id @default(cuid())\n  workspaceId String\n  workspace   AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  name        String\n  industry    String?\n  email       String?\n  phone       String?\n  website     String?\n  // Secure token for client portal access — replaces raw client ID in portal URL\n  portalToken String          @unique @default(cuid())\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  projects        Project[]\n  notices         ClientNotice[]\n  brandBrain      BrandBrain?\n  brandUpdates    BrandUpdate[]\n  contentRequests ContentRequest[]\n}\n\n// ─── Projects ─────────────────────────────────────────────────────────────────\n\nmodel Project {\n  id                   String          @id @default(cuid())\n  workspaceId          String\n  workspace            AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  clientId             String\n  client               Client          @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  // Links a project back to the Brain request it was created from, so the\n  // execution view can load the approved department canvases (BrainArtifact).\n  clientRequestId      String?\n  name                 String\n  goal                 String?\n  type                 String?\n  stage                String          @default(\"briefing\")\n  priority             String          @default(\"medium\")\n  deadline             String?\n  proposalStatus       String?\n  proposalPricing      String?\n  proposalScope        String?\n  proposalSentAt       String?\n  // JSON-encoded string array of assigned agent IDs\n  agents               String          @default(\"[]\")\n  // Execução durável da produção (não depende mais do navegador): o motor marca\n  // o progresso no banco; um cron recupera projetos travados.\n  // executionStatus: idle | pending | running | done | failed\n  executionStatus      String          @default(\"idle\")\n  executionRequestedAt DateTime?\n  executionStartedAt   DateTime?\n  executionFinishedAt  DateTime?\n  executionAttempts    Int             @default(0)\n  executionError       String?\n\n  // ── A ESTEIRA: os três carimbos que fazem o projeto andar ──────────────────\n  // São DECISÕES, por isso ficam gravadas. O resto da fase é DERIVADO do dado\n  // real (lib/agency/esteira/fases.ts) — campo de status escrito à mão mente em\n  // duas semanas. Estes três não são status: são momentos que aconteceram.\n  //\n  // O portão de direção: a produção inteira só dispara depois que o cliente\n  // avaliza o caminho. Aprovar direção é barato; refazer um mês de produção não.\n  directionApprovedAt DateTime?\n  // O PM apresentou o pacote de UMA vez. Antes disso o cliente não recebe\n  // entrega solta — agência com cinco bocas parece desorganizada.\n  presentedAt         DateTime?\n  // O aval final do cliente. A partir daqui, implementação e ciclo mensal.\n  clientApprovedAt    DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  deliverables     Deliverable[]\n  materialRequests MaterialRequest[]\n  strategyRooms    StrategyRoom[]\n  activityEvents   ActivityEvent[]\n  tasks            Task[]\n  timelineEvents   TimelineEvent[]\n  briefings        Briefing[]\n  cycles           Cycle[]\n}\n\n// ─── Ciclos ───────────────────────────────────────────────────────────────────\n\n/// O CICLO MENSAL — onde a relação vitalícia acontece.\n///\n/// Um projeto que nunca fecha não é medível: nada é entregue de fato, nada é\n/// comparado, o painel nunca fica verde. Por isso a operação contínua não é um\n/// projeto infinito — é uma sequência de ciclos que nascem, entregam, medem e\n/// fecham. É o que permite dizer \"agosto foi melhor que julho\", e é isso que\n/// segura um cliente por anos.\n/// Uma campanha de tráfego pago que ESTA agência criou na conta do cliente.\n///\n/// Existe porque dinheiro precisa de rastro. Sem esta tabela, \"quem mandou\n/// gastar R$ 40 por dia na conta da padaria?\" não teria resposta — só um id\n/// solto dentro da Meta. Aqui ficam o teto que o cliente aprovou, quem\n/// autorizou ligar e quando.\nmodel AdCampaign {\n  id              String    @id @default(cuid())\n  workspaceId     String\n  clientId        String?\n  projectId       String?\n  /// Conexão Meta usada. É por ela que se descobre em qual conta isto vive.\n  connectionId    String\n  /// \"act_...\" — a conta de anúncio do cliente.\n  adAccountId     String\n  /// O id da campanha dentro da Meta.\n  externalId      String\n  /// O conjunto e o anúncio. Uma campanha SEM estes dois não entrega nada — é\n  /// um envelope com verba. Ficam aqui porque ativar a campanha sem subir os\n  /// filhos junto deixa a conta com cara de ligada e gastando zero.\n  adSetId         String?\n  adId            String?\n  /// Resumo legível do público, para o painel e o relatório. Nunca é a fonte\n  /// da verdade da segmentação — essa vive dentro da Meta.\n  audience        String?\n  name            String\n  objective       String\n  dailyBudgetBRL  Float\n  /// O teto que o cliente aprovou POR ESCRITO, congelado no momento da criação.\n  /// Congelado de propósito: se o teto mudar depois, o que foi criado ontem\n  /// continua julgável pelo que valia ontem.\n  approvedCapBRL  Float\n  /// paused | active | ended\n  status          String    @default(\"paused\")\n  /// Quem mandou ligar. Nulo enquanto nunca foi ativada.\n  activatedBy     String?\n  activatedAt     DateTime?\n  /// Quando o guardião de verba freou sozinho, e por quê. Campanha que gasta\n  /// sem entregar é o erro que ninguém percebe até a fatura chegar.\n  pausedByGuardAt DateTime?\n  pausedReason    String?\n  lastError       String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([workspaceId, status])\n  @@index([projectId])\n}\n\n/// A conta do Google Meu Negócio de um cliente.\n///\n/// Existe separada da `MetaConnection` de propósito: o ciclo de vida é outro.\n/// O token do Google EXPIRA em 1h e se renova por refresh token; o da Meta dura\n/// 60 dias e não se renova sozinho. Enfiar os dois na mesma tabela obrigaria\n/// todo leitor a saber de qual provedor aquela linha é antes de usá-la — e é\n/// exatamente aí que se publica na conta errada.\nmodel GoogleConnection {\n  id                    String    @id @default(cuid())\n  workspaceId           String\n  /// Nulo = a conta da própria Dioli. Preenchido = a conta de um cliente.\n  clientId              String?\n  /// \"locations/123456\" — o id do local dentro do Google.\n  locationName          String\n  /// \"accounts/987654\" — a conta que administra o local.\n  accountName           String\n  /// Nome legível: \"Padaria do João — Centro\".\n  title                 String    @default(\"\")\n  accessTokenEncrypted  String\n  /// O refresh token é o que sustenta a conexão viva. Sem ele, a conta cai em\n  /// uma hora e alguém precisa reconectar à mão — o oposto de automático.\n  refreshTokenEncrypted String?\n  tokenExpiresAt        DateTime?\n  status                String    @default(\"connected\") // connected | expired | revoked | error\n  /// Até quando já lemos avaliações. Sem isto, cada rodada reprocessaria o\n  /// histórico inteiro e responderia avaliação de dois anos atrás.\n  reviewsSyncedAt       DateTime?\n  /// A política da API do Business Profile PROÍBE resposta automatizada a\n  /// avaliação \"sem o consentimento prévio e específico do usuário\"\n  /// (docs/plataformas/google/fontes/business-profile-api-politicas.md).\n  /// Nulo = sem consentimento registrado → NENHUMA resposta sai sozinha,\n  /// tudo vira rascunho escalado. Preenchido = quando o cliente autorizou.\n  autoReplyConsentAt    DateTime?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  @@unique([workspaceId, locationName])\n  @@index([clientId])\n}\n\n/// Uma avaliação do Google e o que a agência fez com ela.\n///\n/// Fica no banco porque responder avaliação é PÚBLICO e PERMANENTE: precisa de\n/// rastro de quem respondeu o quê e quando, e de uma trava para não responder\n/// duas vezes a mesma avaliação.\nmodel GoogleReview {\n  id              String    @id @default(cuid())\n  workspaceId     String\n  clientId        String?\n  connectionId    String\n  /// O id da avaliação no Google. É a chave de idempotência.\n  externalId      String\n  reviewerName    String    @default(\"\")\n  starRating      Int       @default(0)\n  comment         String    @default(\"\")\n  createdAtGoogle DateTime?\n  /// pendente | respondida | escalada | ignorada\n  status          String    @default(\"pendente\")\n  /// A resposta que a agência escreveu. Guardada mesmo quando escalada — é o\n  /// rascunho que a gente mostra a quem vai decidir.\n  reply           String?\n  repliedAt       DateTime?\n  /// Por que virou assunto de gente. Avaliação negativa nunca é respondida\n  /// sozinha: resposta errada a cliente irritado é pública e permanente.\n  escalatedReason String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@unique([connectionId, externalId])\n  @@index([workspaceId, status])\n}\n\nmodel Cycle {\n  id          String    @id @default(cuid())\n  projectId   String\n  project     Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  /// Competência do ciclo, sempre AAAA-MM. Um por mês, por projeto.\n  reference   String\n  /// aberto | entregue | fechado\n  status      String    @default(\"aberto\")\n  startsOn    String\n  endsOn      String\n  /// O que este ciclo se comprometeu a entregar (JSON), congelado na abertura.\n  planJson    String    @default(\"[]\")\n  /// Números do fechamento (JSON): o que foi medido no fim.\n  resultsJson String    @default(\"{}\")\n  /// A leitura do ciclo em uma frase — o que melhorou, o que não.\n  summary     String?\n  /// Quando o pacote DESTE ciclo foi mostrado ao cliente. Por ciclo, não por\n  /// projeto: o carimbo do projeto só serve ao pacote inicial, e sem este a\n  /// entrega do mês 2 nunca chegaria a ser apresentada.\n  presentedAt DateTime?\n  closedAt    DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@unique([projectId, reference])\n  @@index([projectId, status])\n}\n\n// ─── Avisos ao cliente ────────────────────────────────────────────────────────\n\n/// O AVISO — a ponte entre \"a esteira precisa de algo\" e \"o cliente ficou sabendo\".\n///\n/// A esteira escreve no portal, mas o portal só existe se o cliente abrir. Sem\n/// esta tabela, um pedido de material podia ficar semanas parado porque ninguém\n/// avisou que ele existia — o projeto travado e a agência achando que a bola\n/// estava com o cliente.\n///\n/// A regra: o aviso NUNCA se perde. Se houver canal automático configurado, ele\n/// sai sozinho e o registro fica como comprovante. Se não houver, o aviso vira\n/// FILA para o time disparar à mão — com o texto e o link já prontos, para não\n/// depender de alguém escrever bem às pressas.\n///\n/// Isso resolve a restrição real do WhatsApp: fora da janela de 24h a Meta só\n/// aceita template aprovado, e aprovação leva dias. Até lá o aviso sai pela mão\n/// de gente, mas sai — e o sistema sabe se saiu.\nmodel ClientNotice {\n  id          String  @id @default(cuid())\n  workspaceId String\n  clientId    String\n  client      Client  @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  projectId   String?\n\n  /// direcao | material | entrega | ciclo\n  kind String\n  /// O que o cliente precisa saber, já redigido para ser lido por ele.\n  body String\n  /// O link do portal que resolve este aviso.\n  link String?\n\n  /// pendente | enviado | falhou | dispensado\n  status     String    @default(\"pendente\")\n  /// whatsapp | email | manual | nenhum\n  channel    String    @default(\"nenhum\")\n  /// Por que não saiu sozinho — para a equipe entender sem adivinhar.\n  failReason String?\n  sentAt     DateTime?\n  /// Quem disparou, quando foi à mão.\n  sentBy     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([workspaceId, status])\n  @@index([clientId, status])\n}\n\n// ─── Deliverables ─────────────────────────────────────────────────────────────\n\nmodel Deliverable {\n  id              String   @id @default(cuid())\n  projectId       String\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  name            String\n  type            String\n  status          String   @default(\"draft\")\n  revisionStatus  String?\n  /// Contrato de visibilidade do Hub (interno | aguardando_publicacao |\n  /// compartilhado). Nasce \"interno\" de propósito: a auditoria do Hub provou\n  /// que o padrão fail-open (\"o que a rota esquecer de filtrar, vaza\") é o\n  /// maior risco do portal. Vira \"compartilhado\" no ato de apresentar ao\n  /// cliente (esteira/marcos.ts, esteira/mes.ts) — nunca por omissão.\n  visibility      String   @default(\"interno\")\n  content         String?\n  clientFeedback  String?\n  lastFeedback    String?\n  ownerAgentId    String?\n  /// De que ciclo mensal esta entrega é. NULO = entrega do pacote inicial (o\n  /// projeto, antes de virar rotina). É a chave que faz o mês 2 existir: sem\n  /// ela a idempotência por especialista vale para sempre e a agência entrega\n  /// uma vez só na vida do cliente.\n  cycleId         String?\n  version         Int      @default(1)\n  // JSON-encoded revision history\n  revisionHistory String   @default(\"[]\")\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  versions DeliverableVersion[]\n\n  @@index([projectId, cycleId])\n}\n\n/// Versão de entregável como registro de primeira classe (Hub, Fase 1, 1.9).\n///\n/// Existe porque a exigência \"gera nova versão sem apagar a anterior\" era\n/// incumprível: a refação sobrescrevia `Deliverable.content` e o histórico JSON\n/// guardava notas, não o corpo — o cliente pedia ajuste e a v1 sumia do mundo.\n/// A regra: cada versão é IMUTÁVEL depois de criada; `Deliverable.content` passa\n/// a ser cache da versão corrente (leitura sempre pode reconstruir pela versão).\n/// O retrofit é preguiçoso de propósito: a versão N nasce com o conteúdo atual\n/// no primeiro momento em que alguém vai sobrescrevê-lo (esteira/versoes.ts).\nmodel DeliverableVersion {\n  id            String      @id @default(cuid())\n  deliverableId String\n  deliverable   Deliverable @relation(fields: [deliverableId], references: [id], onDelete: Cascade)\n  number        Int\n  content       String?\n  mediaAssetIds String      @default(\"[]\")\n  /// Executor que produziu ESTA versão (agente ou \"client:...\" nunca — cliente\n  /// não escreve versão; ele decide sobre ela).\n  createdBy     String?\n  /// O que mudou e em resposta a qual comentário — a memória da refação.\n  note          String?\n  createdAt     DateTime    @default(now())\n\n  approvals ApprovalRequest[]\n\n  // Uma versão por número, por entregável — é o que torna o retrofit idempotente.\n  @@unique([deliverableId, number])\n}\n\n// ─── Material Requests ────────────────────────────────────────────────────────\n\n/// O pedido de material que um agente faz ao cliente.\n///\n/// Regra da casa: o agente ABRE o pedido, o gerente de projeto CONSOLIDA e fala.\n/// O cliente recebe uma mensagem só, com tudo que falta — nunca cinco agentes\n/// pedindo coisas soltas em horários diferentes. Por isso o pedido guarda quem\n/// pediu (para a equipe saber quem está travado) e quando foi enviado ao cliente\n/// (para o PM não cobrar a mesma coisa duas vezes).\nmodel MaterialRequest {\n  id                 String    @id @default(cuid())\n  projectId          String\n  project            Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  type               String\n  description        String\n  status             String    @default(\"pending\")\n  /// Qual agente travou por falta deste material (a3, a2…).\n  requestedByAgentId String?\n  /// Nome legível de quem pediu — vai no resumo que o PM manda.\n  requestedByLabel   String?\n  /// Quando o PM incluiu este pedido na mensagem consolidada ao cliente.\n  askedClientAt      DateTime?\n  requestedAt        DateTime  @default(now())\n  resolvedAt         DateTime?\n\n  @@index([projectId, status])\n}\n\n// ─── Pedido de conteúdo — a PRIMEIRA seta que aponta cliente → agência ────────\n\n/// O pedido que o CLIENTE faz à agência: \"quero uma peça nova\".\n///\n/// Por que NÃO é um MaterialRequest com a seta invertida (a pergunta que o CEO\n/// mandou justificar): o MaterialRequest é o portão de recursos — ele existe\n/// para TRAVAR produção por falta de insumo. `assess-resources` abre um por item\n/// faltante, `esteira/pedidos.ts` consolida e o portal os lista sob \"A produção\n/// está esperando:\". Um pedido do cliente entrando ali apareceria para o próprio\n/// cliente como coisa que ELE deve entregar, e travaria o projeto dele. A seta é\n/// oposta e o efeito é oposto — mesma forma, semântica invertida.\n///\n/// Também não cabe em ClientRequestDb: aquilo é a porta do PROSPECT (briefing,\n/// SDR, proposta). Um cliente que já paga pedindo mais um reels não é um lead\n/// novo; entraria na fila de \"Solicitações\" com status \"new\" e sujaria o funil.\n///\n/// O que este modelo carrega é o MÍNIMO que um especialista precisa para\n/// produzir sem inventar: o que, para quando e para qual objetivo. Nada de\n/// formulário longo — o cliente não preenche.\nmodel ContentRequest {\n  id              String    @id @default(cuid())\n  /// O dono. Vem SEMPRE do token (derivação, nunca comparação — regra da casa\n  /// de 03/08/2026). Cascata porque um pedido sem cliente não significa nada.\n  clientId        String\n  client          Client    @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  /// A solicitação do briefing, quando o cliente veio por lá. Ponteiro sem FK:\n  /// o `/api/admin/reset` mexe nessa tabela por conta própria.\n  clientRequestId String?\n  /// O projeto que recebeu o pedido. Nulo até a triagem — e nulo é honesto:\n  /// cliente sem projeto aberto NÃO ganha tarefa inventada.\n  projectId       String?\n  /// Título curto derivado da descrição, só para a lista da caixa de entrada.\n  title           String\n  /// O QUE ele quer, nas palavras dele. NUNCA vazio — pedido mudo não vira\n  /// tarefa muda: a rota devolve a pergunta em vez de gravar.\n  description     String\n  /// PARA QUAL OBJETIVO. Também obrigatório: sem o porquê, o especialista\n  /// escolhe o ângulo sozinho — que é exatamente inventar verdade.\n  objective       String\n  /// PARA QUANDO, quando o cliente sabe dizer. Opcional de propósito: a maioria\n  /// não sabe, e obrigar a chutar data produz prazo falso no sistema.\n  desiredFor      DateTime?\n  /// URLs de material já enviado pelo portal (/api/media). JSON de strings.\n  attachmentsJson String    @default(\"[]\")\n  /// novo | triado | recusado. \"triado\" = virou Task (o elo com a esteira).\n  status          String    @default(\"novo\")\n  /// A decisão de ESCOPO, tomada por gente: \"ciclo\" (entra no ciclo corrente)\n  /// ou \"extra\" (escopo adicional a combinar). Nasce NULA de propósito — preço\n  /// e prazo não se inventam, e o plano do ciclo é congelado na abertura.\n  scopeDecision   String?\n  /// A tarefa criada na triagem. É por aqui que o pedido encontra a esteira.\n  taskId          String?\n  /// Quem triou e quando — pedido parado sem dono é vazamento.\n  triagedBy       String?\n  triagedAt       DateTime?\n  /// Por que foi recusado, em linguagem que o cliente lê.\n  declineReason   String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([clientId, status])\n  @@index([status, createdAt])\n}\n\n// ─── Brand Brain ─────────────────────────────────────────────────────────────\n\nmodel BrandBrain {\n  id             String   @id @default(cuid())\n  clientId       String   @unique\n  client         Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  brandName      String?\n  tagline        String?\n  primaryColor   String?\n  secondaryColor String?\n  typography     String?\n  tone           String?\n  values         String   @default(\"[]\")\n  targetAudience String?\n  positioning    String?\n  updatedAt      DateTime @updatedAt\n}\n\n// ─── Strategy Room ────────────────────────────────────────────────────────────\n\nmodel StrategyRoom {\n  id           String   @id @default(cuid())\n  projectId    String   @unique\n  project      Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  clientId     String?\n  status       String   @default(\"generating\")\n  // Full StrategyRoom object (specialists, debate turns, consensus, executive\n  // summary, synthesis) serialized as JSON — pragmatic single-column storage.\n  analysisJson String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\n// ─── Briefings ─────────────────────────────────────────────────────────────\n\nmodel Briefing {\n  id              String   @id @default(cuid())\n  projectId       String\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  clientId        String\n  goal            String\n  audience        String   @default(\"\")\n  keyMessage      String   @default(\"\")\n  deliverables    String   @default(\"\")\n  deadline        String   @default(\"\")\n  successCriteria String   @default(\"\")\n  notes           String?\n  status          String   @default(\"pending_analysis\")\n  createdAt       DateTime @default(now())\n}\n\n// ─── Brand Updates ─────────────────────────────────────────────────────────\n// Pending brand suggestions (client portal / manual / upload / parsed) queued\n// before being applied to the client's BrandBrain.\n\nmodel BrandUpdate {\n  id             String   @id @default(cuid())\n  clientId       String\n  client         Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  field          String\n  suggestedValue String\n  currentValue   String?\n  source         String   @default(\"manual\")\n  status         String   @default(\"pending\")\n  note           String?\n  fileName       String?\n  submittedAt    DateTime @default(now())\n}\n\n// ─── Brain Updates (learning loop) ────────────────────────────────────────────\n// Department-scoped feedback proposals from approved deliverables / quality\n// reviews / human edits. NEVER auto-applied — a human applies each one, which\n// then mutates the actual BrandBrain. Distinct from BrandUpdate (portal/manual\n// brand-field queue) — this captures the Brain's own learning signal.\n\nmodel BrainUpdate {\n  id              String    @id @default(cuid())\n  clientRequestId String\n  department      String\n  fieldChanged    String // which brand brain field\n  previousValue   String?\n  proposedValue   String\n  source          String // \"approved_delivery\" | \"quality_review\" | \"human_edit\"\n  status          String    @default(\"pending\") // \"pending\" | \"applied\" | \"rejected\"\n  createdAt       DateTime  @default(now())\n  appliedAt       DateTime?\n}\n\n// ─── Integration Configs ──────────────────────────────────────────────────────\n\nmodel DbIntegrationConfig {\n  id               String          @id @default(cuid())\n  workspaceId      String\n  workspace        AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  integrationId    String\n  configured       Boolean         @default(false)\n  selectedModel    String?\n  configWorkspace  String?\n  accountId        String?\n  folder           String?\n  webhookUrl       String?\n  // API key storage — AES-256-GCM encrypted (see lib/security/crypto.ts).\n  // apiKeyHint is a non-sensitive display string e.g. \"sk-ant-…a1b2\".\n  apiKeyEncrypted  String?\n  apiKeyHint       String?\n  lastTestStatus   String          @default(\"not_run\")\n  lastTestAt       DateTime?\n  lastTestMessage  String?\n  lastConfiguredAt DateTime?\n\n  @@unique([workspaceId, integrationId])\n}\n\nmodel DbAgentProviderConfig {\n  id               String          @id @default(cuid())\n  workspaceId      String\n  workspace        AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  agentId          String\n  selectedProvider String          @default(\"rule_based\")\n  selectedModel    String?\n\n  @@unique([workspaceId, agentId])\n}\n\n// ─── Tasks ────────────────────────────────────────────────────────────────────\n\nmodel Task {\n  id            String   @id @default(cuid())\n  projectId     String\n  project       Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  title         String\n  description   String?\n  agentId       String?\n  status        String   @default(\"pending\")\n  dueDate       String?\n  deliverableId String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\n// ─── Timeline Events ──────────────────────────────────────────────────────────\n\nmodel TimelineEvent {\n  id        String   @id @default(cuid())\n  projectId String\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  type      String\n  label     String\n  dept      String   @default(\"pm\")\n  detail    String?\n  timestamp DateTime @default(now())\n}\n\n// ─── Activity Events ─────────────────────────────────────────────────────────\n\nmodel ActivityEvent {\n  id          String          @id @default(cuid())\n  workspaceId String\n  workspace   AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  projectId   String?\n  project     Project?        @relation(fields: [projectId], references: [id])\n  type        String\n  message     String\n  clientId    String?\n  timestamp   DateTime        @default(now())\n}\n\n// ─── AI Run Logs ──────────────────────────────────────────────────────────────\n// Tracks every department intelligence execution — provider used, fallback\n// status, prompt/output summaries, and warnings. Persisted per workspace.\n\nmodel AIRunLog {\n  id             String          @id @default(cuid())\n  workspaceId    String\n  workspace      AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  departmentId   String\n  projectId      String?\n  provider       String          @default(\"rule_based\")\n  model          String          @default(\"rule_based\")\n  status         String          @default(\"success\")\n  fallbackUsed   Boolean         @default(false)\n  fallbackReason String?\n  promptSummary  String?\n  outputSummary  String?\n  warnings       String          @default(\"[]\")\n  createdAt      DateTime        @default(now())\n}\n\n// ─── Continuous SDR Training V3 ───────────────────────────────────────────────\n\nmodel TrainingBatch {\n  id           String   @id @default(cuid())\n  mode         String\n  triggeredBy  String\n  totalRuns    Int\n  passCount    Int\n  warningCount Int\n  failCount    Int\n  averageScore Int\n  durationMs   Int\n  createdAt    DateTime @default(now())\n\n  runs DbSimulationRun[]\n}\n\nmodel DbSimulationRun {\n  id               String         @id\n  batchId          String?\n  batch            TrainingBatch? @relation(fields: [batchId], references: [id])\n  agentId          String\n  scenarioOrigin   String\n  scenarioSeed     String?\n  scenarioName     String\n  scenarioMetadata String         @default(\"{}\")\n  score            Int\n  verdict          String\n  transcript       String         @default(\"[]\")\n  finalScope       String?\n  finalEstimate    String?\n  sdrHandoff       String?\n  issues           String         @default(\"[]\")\n  recommendations  String         @default(\"[]\")\n  engineVersion    String\n  createdAt        DateTime       @default(now())\n}\n\nmodel DbAgentSuggestion {\n  id              String    @id\n  agentId         String\n  title           String\n  problem         String\n  evidence        String\n  suggestedChange String\n  impact          String\n  status          String    @default(\"pending\")\n  sourceRunIds    String    @default(\"[]\")\n  createdAt       DateTime  @default(now())\n  decidedAt       DateTime?\n}\n\nmodel TrainingAlert {\n  id            String    @id @default(cuid())\n  agentId       String\n  title         String\n  message       String\n  severity      String\n  triggerType   String\n  relatedRunIds String    @default(\"[]\")\n  status        String    @default(\"active\")\n  createdAt     DateTime  @default(now())\n  resolvedAt    DateTime?\n}\n\nmodel BrainChangeRequest {\n  id                  String    @id @default(cuid())\n  agentId             String\n  title               String\n  sourceSuggestionIds String    @default(\"[]\")\n  proposedChange      String\n  status              String    @default(\"pending_review\")\n  createdAt           DateTime  @default(now())\n  approvedAt          DateTime?\n  appliedAt           DateTime?\n  // Governance fields (Brain Director layer)\n  source              String    @default(\"manual\")\n  department          String    @default(\"client-service-sdr\")\n  category            String    @default(\"department_logic\")\n  description         String    @default(\"\")\n  rationale           String    @default(\"\")\n  expectedImpact      String    @default(\"\")\n  riskLevel           String    @default(\"medium\")\n  requestedBy         String    @default(\"system\")\n  approvalRequiredBy  String    @default(\"brain_director\")\n  reviewedAt          DateTime?\n  reviewNote          String?\n}\n\n// Brain version history — every applied change increments the version.\n// Governance only: no runtime mutation of Brain logic yet.\nmodel BrainVersion {\n  id              String   @id @default(cuid())\n  version         String   @unique\n  summary         String\n  changeRequestId String?\n  createdAt       DateTime @default(now())\n}\n\n// ─── Foundation Sprint: Brain Pipeline Persistence ────────────────────────────\n\n// DB-backed client request — source of truth for the real workflow.\n// Zustand localStorage remains as labeled prototype/simulation layer.\nmodel ClientRequestDb {\n  id              String   @id @default(cuid())\n  workspaceId     String?\n  clientId        String?\n  businessName    String\n  segment         String   @default(\"\")\n  // JSON-encoded string arrays\n  services        String   @default(\"[]\")\n  objectives      String   @default(\"[]\")\n  status          String   @default(\"new\")\n  source          String   @default(\"briefing\")\n  rawContext      String   @default(\"\")\n  briefingJson    String?\n  sdrHandoffJson  String?\n  attachmentsJson String   @default(\"[]\")\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  artifacts     BrainArtifact[]\n  approvals     ApprovalRequest[]\n  evidenceItems EvidenceItem[]\n  portalAccess  PortalAccess[]\n  messages      PortalMessage[]\n}\n\n// Client ↔ team conversation. A thread belongs to um CLIENTE — não a uma\n// solicitação. authorRole distinguishes who wrote it; the read flags drive\n// unread badges on each side.\nmodel PortalMessage {\n  /// Nulo para cliente criado DIRETO (sem briefing público) — MESMO par de\n  /// chaves que o ApprovalRequest e o BrainArtifact já adotaram em 04/08/2026.\n  /// Era obrigatório, e por isso o cliente-piloto (Foocci, criado direto) não\n  /// conseguia MANDAR mensagem nenhuma: a rota devolvia 404 \"No conversation\n  /// thread for this token yet\" e a bolha voltava para a caixa de texto para\n  /// sempre. O CEO tentou falar com a agência pelo portal e não conseguiu.\n  id              String           @id @default(cuid())\n  clientRequestId String?\n  clientRequest   ClientRequestDb? @relation(fields: [clientRequestId], references: [id], onDelete: Cascade)\n  /// O dono quando não há solicitação. Sem FK, pelo mesmo motivo do\n  /// ApprovalRequest: a limpeza total (`/api/admin/reset`) já apaga a tabela\n  /// inteira, e um FK novo redefiniria a tabela para todo mundo.\n  ///\n  /// A partir daqui TODA mensagem nova carimba o clientId quando ele é\n  /// derivável — inclusive as que também têm clientRequestId. É o que mantém a\n  /// conversa ÚNICA por cliente mesmo depois de o cliente ganhar (ou trocar de)\n  /// solicitação: a leitura une as duas chaves.\n  clientId        String?\n  authorRole      String // \"client\" | \"team\"\n  authorName      String           @default(\"\")\n  body            String\n  readByTeam      Boolean          @default(false)\n  readByClient    Boolean          @default(false)\n  createdAt       DateTime         @default(now())\n\n  @@index([clientRequestId, createdAt])\n  @@index([clientId, createdAt])\n  /// A caixa de entrada da agência conta por aqui: quantas do cliente ainda não\n  /// foram lidas pela equipe. Escrito em 11 lugares e, até 05/08/2026, lido em\n  /// NENHUM — a mensagem gravava e morria.\n  @@index([readByTeam, authorRole])\n}\n\n// A planned/scheduled social post — the unit of the universal Planner. One post\n// composed once, targeting many networks, scheduled to a date. Surfaces on the\n// agency planner (edit) and the client portal Social tab (read-only calendar).\nmodel SocialPost {\n  id              String    @id @default(cuid())\n  workspaceId     String\n  clientId        String?\n  clientRequestId String? // links it to the client's portal thread\n  caption         String    @default(\"\")\n  networks        String    @default(\"[]\") // JSON array: instagram|facebook|tiktok|linkedin|youtube|pinterest\n  format          String    @default(\"feed\") // feed|reel|story|carousel|video\n  pillar          String? // content pillar\n  mediaUrl        String? // link to the creative (Drive/etc.) until native storage\n  /// As telas do CARROSSEL, em JSON. Uma peça só com várias imagens — por isso\n  /// não cabe em `mediaUrl`. Fica vazio em todo formato que não é carrossel.\n  mediaUrlsJson   String    @default(\"[]\")\n  /// As telas descritas pelo especialista, uma por linha. É o que o gerador de\n  /// arte usa para desenhar CADA tela — sem isso, um carrossel de 5 imagens\n  /// sairia com 5 variações da mesma cena.\n  scenesJson      String    @default(\"[]\")\n  scriptJson      String? // AI video/reel script (hook, scenes, cta, audio)\n  /// Contrato de visibilidade do Hub. Nasce \"interno\" (fail-closed); o fluxo\n  /// que agenda para o calendário do cliente (esteira/publicacao.ts) grava\n  /// \"compartilhado\" explicitamente. A rota do portal filtra por este campo —\n  /// a lição da auditoria: rota nova escrita sem cuidado não pode vazar por padrão.\n  visibility      String    @default(\"interno\")\n  scheduledFor    DateTime?\n  status          String    @default(\"draft\") // draft|scheduled|approved|published|failed\n  // Quem gerou esta peça (o `Deliverable`) — é a chave de idempotência do\n  // agendamento: entrega que já virou calendário não vira de novo.\n  deliverableId   String?\n  // Preenchidos na publicação. `externalPostId` é o que o relatório mensal usa\n  // para pedir métricas à Meta; sem ele o report vira chute.\n  externalPostId  String?\n  permalink       String?\n  publishedAt     DateTime?\n  // Último motivo de falha, em linguagem de gente. Fica visível ao time em vez\n  // de morrer no log do servidor.\n  lastError       String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([workspaceId, scheduledFor])\n  @@index([deliverableId])\n  @@index([status, scheduledFor])\n  @@index([clientRequestId])\n}\n\n// One record per department approval — persists canvas payload + gate + trace.\nmodel BrainArtifact {\n  id                String           @id @default(cuid())\n  /// Nulo para cliente criado DIRETO (sem briefing público) — mesmo par de\n  /// chaves do SocialPost e do ApprovalRequest. Era obrigatório, e por isso a\n  /// memória de LEITURA DO FEED (department \"leitura-do-cliente\") não tinha\n  /// onde nascer justamente no cliente-piloto: post direto tem clientId e\n  /// clientRequestId NULO, então a síntese nunca era gravada nem lida e o\n  /// estilo do feed voltava vazio em silêncio.\n  clientRequestId   String?\n  clientRequest     ClientRequestDb? @relation(fields: [clientRequestId], references: [id], onDelete: Cascade)\n  /// O dono quando não há solicitação. Sem FK, pelo mesmo motivo do\n  /// ApprovalRequest: a limpeza total (`/api/admin/reset`) já apaga a tabela\n  /// inteira, e um FK novo redefiniria a tabela para todo mundo.\n  clientId          String?\n  department        String\n  canvasId          String\n  canvasJson        String\n  qualityGateJson   String?\n  cognitiveFlowJson String?\n  version           Int              @default(1)\n  status            String           @default(\"approved\")\n  approvedAt        DateTime         @default(now())\n  approvedBy        String           @default(\"internal\")\n  createdAt         DateTime         @default(now())\n\n  @@index([clientId, department])\n}\n\n// Formal approval flow — one record per department review cycle.\nmodel ApprovalRequest {\n  id                   String              @id @default(cuid())\n  /// Nulo para cliente criado DIRETO (sem briefing público). No lançamento da\n  /// Foocci (03/08/2026) TODA aprovação exigia ClientRequestDb — cliente direto\n  /// não tinha como aprovar nada: o portal dizia \"Esperando você\" e a aba de\n  /// Aprovações ficava vazia. A posse passa a ser: clientRequestId OU clientId.\n  clientRequestId      String?\n  clientRequest        ClientRequestDb?    @relation(fields: [clientRequestId], references: [id], onDelete: Cascade)\n  /// O dono quando não há solicitação — mesmo par de chaves do SocialPost.\n  /// Nunca vem de query/corpo no caminho público: deriva do token (regra da\n  /// casa, 03/08/2026).\n  clientId             String?\n  artifactId           String?\n  department           String\n  requestedBy          String              @default(\"internal\")\n  status               String              @default(\"pending\")\n  reviewedBy           String?\n  reviewedAt           DateTime?\n  expiresAt            DateTime?\n  /// A dúvida do cliente NÃO é decisão (Fase 2, caminho C): o status continua\n  /// \"pending\", mas o relógio do prazo não pode correr contra ele enquanto a\n  /// bola está com a agência. Preenchido = dúvida aberta, prazo pausado; a\n  /// resposta da agência devolve o tempo pausado ao `expiresAt` e limpa o campo\n  /// (approval-service.addApprovalComment).\n  questionOpenedAt     DateTime?\n  reviewNote           String?\n  clientVisible        Boolean             @default(false)\n  /// QUAL versão está sendo decidida — \"aprovei a v3\" não era registrável\n  /// (Fase 1, 1.10) e o cliente podia aprovar lendo conteúdo de outra entrega\n  /// (achado A2). O vínculo por FK mata o casamento heurístico por ordem.\n  deliverableVersionId String?\n  deliverableVersion   DeliverableVersion? @relation(fields: [deliverableVersionId], references: [id])\n  /// Posts do calendário que ESTE card decide (JSON de ids de SocialPost).\n  /// Preenchido = a origem é o calendário (rota /api/social-posts/aprovacao);\n  /// a decisão do cliente propaga o status a estes posts (aprovar → \"approved\",\n  /// ajuste/recusa → \"revision_requested\"). Vazio = aprovação do fluxo Brain.\n  sourcePostIdsJson    String              @default(\"[]\")\n  createdAt            DateTime            @default(now())\n  updatedAt            DateTime            @updatedAt\n\n  comments ApprovalComment[]\n\n  @@index([clientId])\n}\n\nmodel ApprovalComment {\n  id                String          @id @default(cuid())\n  approvalRequestId String\n  approvalRequest   ApprovalRequest @relation(fields: [approvalRequestId], references: [id], onDelete: Cascade)\n  authorName        String\n  authorRole        String          @default(\"internal\")\n  /// \"comment\" | \"question\" | \"answer\". A dúvida fica PRESA ao card (Fase 2,\n  /// caminho C) — não numa thread geral desconectada, que era o problema.\n  kind              String          @default(\"comment\")\n  body              String\n  isClientVisible   Boolean         @default(false)\n  createdAt         DateTime        @default(now())\n}\n\n// Evidence items tied to a request or artifact — persisted to DB.\nmodel EvidenceItem {\n  id              String           @id @default(cuid())\n  clientRequestId String?\n  clientRequest   ClientRequestDb? @relation(fields: [clientRequestId], references: [id])\n  artifactId      String?\n  department      String\n  type            String\n  label           String\n  valueJson       String           @default(\"{}\")\n  sourceUrl       String?\n  createdAt       DateTime         @default(now())\n}\n\n// ─── Meta (Instagram / Facebook / WhatsApp) connected accounts ──────────────────\n// One row per connected asset (an IG business account, a FB page, or a WhatsApp\n// number). Populated by the OAuth flow in app/api/meta/*. The long-lived access\n// token is AES-256-GCM encrypted at rest (see lib/security/crypto.ts) — exactly\n// like AI keys in DbIntegrationConfig. The Meta APP credentials (App ID / App\n// Secret) live in DbIntegrationConfig (integrationId \"int-meta\"), NOT here.\nmodel MetaConnection {\n  id                   String          @id @default(cuid())\n  workspaceId          String\n  workspace            AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  // Optional: a connection can belong to a specific client, or to the agency\n  // itself (clientId null = the agency's own accounts).\n  clientId             String?\n  // instagram | facebook | whatsapp\n  platform             String\n  // Human-readable label: IG handle, Page name, or WhatsApp display name.\n  name                 String          @default(\"\")\n  // The platform's native id: IG Business Account id, FB Page id, or WABA\n  // phone-number id — the id the Graph API publish/insights calls target.\n  externalId           String\n  // Long-lived access token — ENCRYPTED (iv:tag:ciphertext). Page tokens for\n  // FB/IG do not expire; user tokens last ~60 days (see tokenExpiresAt).\n  accessTokenEncrypted String\n  tokenHint            String?\n  tokenExpiresAt       DateTime?\n  // Granted scopes/permissions (JSON array) and any extra platform metadata\n  // (e.g. linked page id, business id) as JSON — avoids new columns per field.\n  scopes               String          @default(\"[]\")\n  metaJson             String          @default(\"{}\")\n  status               String          @default(\"connected\") // connected | expired | revoked | error\n  connectedAt          DateTime        @default(now())\n  lastSyncedAt         DateTime?\n  createdAt            DateTime        @default(now())\n  updatedAt            DateTime        @updatedAt\n\n  @@unique([workspaceId, platform, externalId])\n  @@index([workspaceId, platform])\n  @@index([clientId])\n}\n\n// WhatsApp conversation log — the single-inbox history. One row per message,\n// inbound (client → agency) or outbound (agency → client), so the agency can\n// read + reply from inside the system using ONE number. Populated inbound by\n// the webhook and outbound by the reply endpoint.\nmodel WhatsAppMessage {\n  id              String   @id @default(cuid())\n  workspaceId     String\n  // The API phone-number-id this conversation belongs to (our number).\n  phoneNumberId   String   @default(\"\")\n  // The client's WhatsApp id (their phone in wa_id form).\n  contactWaId     String\n  contactName     String?\n  direction       String // \"in\" | \"out\"\n  type            String   @default(\"text\") // text | template | image | ...\n  body            String   @default(\"\")\n  externalId      String? // Meta message id (wamid…) — for dedupe + status\n  status          String? // sent | delivered | read | failed (outbound)\n  clientRequestId String?\n  timestamp       DateTime @default(now())\n\n  @@index([workspaceId, contactWaId, timestamp])\n  @@index([externalId])\n}\n\n// Outbox / dedupe ledger for WhatsApp notifications. One row per ActivityEvent\n// we act on, so the poller never sends the same \"whatsapp_notify\" twice. Owned\n// by the Meta integration (lib/integrations/meta/notifications.ts).\nmodel WhatsAppOutbox {\n  id                String   @id @default(cuid())\n  workspaceId       String\n  // The ActivityEvent this row was created for — unique so a re-run is a no-op.\n  activityEventId   String   @unique\n  kind              String   @default(\"proposal_sent\")\n  toPhone           String?\n  status            String   @default(\"sent\") // sent | failed | skipped\n  externalMessageId String?\n  error             String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@index([workspaceId, status])\n}\n\n// Granular, time-limited portal access per client request.\nmodel PortalAccess {\n  id              String           @id @default(cuid())\n  token           String           @unique @default(cuid())\n  clientRequestId String?\n  clientRequest   ClientRequestDb? @relation(fields: [clientRequestId], references: [id])\n  clientId        String?\n  grantedAt       DateTime         @default(now())\n  expiresAt       DateTime?\n  revokedAt       DateTime?\n  lastAccessedAt  DateTime?\n  accessCount     Int              @default(0)\n  createdAt       DateTime         @default(now())\n}\n\n// ─── Radar Dioli — biblioteca viva de tendências/atualizações de mercado ────\n// O acervo que abastece TODOS os agentes (insumo) e as diretrizes da Qualidade.\n// Governança: fonte \"official\" (a própria plataforma — Meta/TikTok/Google) entra\n// ATIVA sem validação; \"trend\" (não-oficial) entra PENDENTE até um humano aprovar.\nmodel MarketInsight {\n  id          String          @id @default(cuid())\n  workspaceId String\n  workspace   AgencyWorkspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n  // Domínio: social | design | paid-traffic | analytics | seo | general\n  domain      String\n  // Tópico — chave de versionamento: nova entrada do mesmo tópico arquiva a antiga\n  // (o \"era assim → agora é assim\").\n  topic       String\n  title       String\n  // A diretriz vigente (\"agora é assim\") — o insumo que os agentes usam.\n  guidance    String\n  // official = da própria plataforma → entra ATIVA sem validação humana.\n  // trend    = não-oficial → entra PENDENTE até validação humana.\n  source      String          @default(\"trend\")\n  sourceName  String?\n  sourceUrl   String?\n  // active | pending | archived | rejected\n  status      String          @default(\"pending\")\n  approvedBy  String?\n  approvedAt  DateTime?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  @@index([workspaceId, domain, status])\n  @@index([workspaceId, topic])\n}\n\n// ─── Mídia ────────────────────────────────────────────────────────────────────\n\n/// O ARQUIVO. Foi o buraco mais caro encontrado no raio-X de 02/08/2026: até\n/// aqui, nenhum byte de mídia era gravado em lugar nenhum — nem de entrada\n/// (o vídeo que o cliente manda) nem de saída (a arte que a IA gera).\n///\n/// O que isso quebrava, em três serviços de uma vez: a dona do salão não tinha\n/// por onde mandar os vídeos dela; o pet shop não tinha por onde mandar o logo;\n/// e a imagem gerada pelo Design virava base64 dentro de uma coluna de texto do\n/// banco (megabytes por peça) ou uma URL da OpenAI que expira em ~1 hora.\n///\n/// Desenho: o BYTE mora no volume persistente do Railway — o mesmo que já\n/// guarda o banco, e que o `scripts/start.sh` trata como armazenamento durável.\n/// Aqui mora só o registro. Nenhuma coluna guarda conteúdo binário.\n///\n/// A segurança é por DERIVAÇÃO, não por comparação: o dono é gravado aqui, e a\n/// rota de download resolve o dono a partir do token do portal — nunca da URL.\n/// O caminho em disco é derivado do id, nunca do nome que o cliente enviou, o\n/// que mata travessia de diretório por construção.\nmodel MediaAsset {\n  id              String   @id @default(cuid())\n  workspaceId     String\n  /// O dono. Um dos dois sempre presente — é o que a rota de download confere.\n  clientRequestId String?\n  clientId        String?\n  projectId       String?\n  /// inbound = o cliente mandou · generated = a IA produziu · deliverable = vai ao cliente\n  kind            String   @default(\"inbound\")\n  /// Nome original. É PII em potencial (\"orcamento-joao-silva.pdf\") — fica aqui,\n  /// nunca em log.\n  fileName        String\n  mimeType        String\n  sizeBytes       Int\n  /// Impressão digital do conteúdo: permite detectar reenvio do mesmo arquivo.\n  sha256          String\n  /// Caminho relativo dentro do diretório de mídia. Derivado do id, nunca do\n  /// nome enviado.\n  storagePath     String\n  /// Quem enviou, em linguagem de gente (\"cliente\", \"Agente de Design\").\n  uploadedBy      String   @default(\"cliente\")\n  createdAt       DateTime @default(now())\n\n  @@index([clientRequestId, createdAt])\n  @@index([workspaceId, kind])\n  @@index([sha256])\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

